; DMAIN.S - DASH CORE ENTRY & EVENT LOOP
START:
    CLD                     ; CLEAR DECIMAL MODE
    
    ; SET INITIAL PAGE TO SYSTEM (0)
    LDA #0
    STA CURRPAGE
    
    ; FORCE INITIAL REDRAW
    LDA #1
    STA NEEDREDRAW

EVENTLOOP:
    LDA NEEDREDRAW
    BEQ POLLINPUT
    
    ; CLEAR NEEDREDRAW FIRST
    LDA #0
    STA NEEDREDRAW
    
    ; CALL PAGE DISPATCH TRAMPOLINE
    JSR DISPATCHPAGE

POLLINPUT:
    JSR $FFE4               ; KERNALGETIN (POLL KEYBOARD)
    TAX                     ; SAVE CHARACTER IN X
    BEQ EVENTLOOP           ; NO KEY PRESSED, LOOP
    
    ; CHECK KEYS
    CPX #$85                ; F1
    BEQ SELECTSYS
    CPX #$86                ; F3
    BEQ SELECTAPP
    CPX #$87                ; F5
    BEQ SELECTVMM
    CPX #$54                ; 'T'
    BEQ TRYRUNVMMTEST
    CPX #$74                ; 'T'
    BEQ TRYRUNVMMTEST
    CPX #$52                ; 'R'
    BEQ SETREDRAW
    CPX #$72                ; 'R'
    BEQ SETREDRAW
    CPX #$51                ; 'Q'
    BEQ EXITAPP
    CPX #$71                ; 'Q'
    BEQ EXITAPP
    JMP EVENTLOOP           ; IGNORE OTHER KEYS

SELECTSYS:
    LDA #0
    STA CURRPAGE
    LDA #1
    STA NEEDREDRAW
    JMP EVENTLOOP

SELECTAPP:
    LDA #1
    STA CURRPAGE
    LDA #1
    STA NEEDREDRAW
    JMP EVENTLOOP

SELECTVMM:
    LDA #2
    STA CURRPAGE
    LDA #1
    STA NEEDREDRAW
    JMP EVENTLOOP

; TRYRUNVMMTEST - 'T'/'T' IS ONLY WIRED ON THE VMM TEST PAGE (CURRPAGE 2);
; PRESSED ON ANY OTHER PAGE, IT IS SILENTLY IGNORED.
TRYRUNVMMTEST:
    LDA CURRPAGE
    CMP #2
    BEQ TRVT_ONVMMPAGE
    JMP EVENTLOOP
TRVT_ONVMMPAGE:
    JSR DVMMRUNTEST
    LDA #1
    STA NEEDREDRAW
    JMP EVENTLOOP

SETREDRAW:
    LDA #1
    STA NEEDREDRAW
    JMP EVENTLOOP

EXITAPP:
    LDA #$4C                ; DOS_EXIT FUNCTION CODE
    JSR $1000               ; CALL OS SERVICE BUS
    RTS                     ; SAFE FALLBACK

DISPATCHPAGE:
    ; 1. VALIDATE CURRPAGE (0..2). RESET TO 0 IF OUT OF RANGE.
    LDA CURRPAGE
    CMP #3
    BCC PAGEVALID
    LDA #0
    STA CURRPAGE
PAGEVALID:
    ; 2. SETUP TRAMPOLINE CALL
    LDA CURRPAGE
    ASL A                     ; MULTIPLY BY 2 TO GET OFFSET
    TAY
    
    LDA PAGEROUTINETABLE, Y
    STA $70
    INY
    LDA PAGEROUTINETABLE, Y
    STA $71
    
    ; 3. PUSH RETURN ADDRESS - 1 (DISPATCHRETURN - 1) ON STACK
    LDA #>DISPATCHRETURNMINUSONE
    PHA
    LDA #<DISPATCHRETURNMINUSONE
    PHA
    
    ; 4. JMP INDIRECT THROUGH ZP $70
    JMP ($0070)

DISPATCHRETURNMINUSONE:
    .BYTE 0                 ; ONE-BYTE FILLER SO RTS LANDS ON DISPATCHRETURN
DISPATCHRETURN:
    RTS

; DASH IS BUILT FROM A SINGLE ENTRY FILE: THIS FILE PULLS IN THE OTHER SIX
; SOURCES VIA .INCLUDE, IN THE SAME ORDER THE PRE-.INCLUDE MULTI-FILE CASM
; COMMAND LINE USED. DDATA.S MUST STAY LAST SO ITS DATA BLOCK FOLLOWS ALL
; CODE. THIS IS NOW THE ONLY PLACE THAT ORDER IS SPECIFIED -- BOTH NATIVE
; CASM (CASM DMAIN.S /O:DASH.PRG) AND THE CA65 CROSS-CHECK (DASH_WRAPPER.S,
; WHICH JUST INCLUDES THIS FILE) READ IT FROM HERE.
.INCLUDE "DSCR.S"
.INCLUDE "DFMT.S"
.INCLUDE "DSYS.S"
.INCLUDE "DAPP.S"
.INCLUDE "DVMM.S"
.INCLUDE "DDATA.S"
